async()=>{const wait=async f=>{for(let i=0;i<100;i++){if(f())return;await new Promise(r=>setTimeout(r,40));}throw Error('UI timeout')};await wait(()=>typeof window.qaReleaseStudy==='function');const field=document.querySelector('input[aria-label="Synthetic notes"]');field.focus();field.value='Still writing';const before={tag:document.activeElement.tagName,label:document.activeElement.getAttribute('aria-label')};window.qaReleaseStudy();await wait(()=>document.querySelector('.head-guided-learning h3'));await new Promise(r=>setTimeout(r,200));return{synthetic:true,before,after:{tag:document.activeElement.tagName,label:document.activeElement.getAttribute('aria-label'),text:document.activeElement.textContent},heading:document.querySelector('.head-guided-learning h3').textContent,errors:window.qaErrors||[]}}
